
'use strict';
const KEY='mv_v1';
const uid=()=> (crypto&&crypto.randomUUID)?crypto.randomUUID():('v_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2));
let db=JSON.parse(localStorage.getItem(KEY)||'null')||{vehicles:[],maintenance:[],fuel:[],obligations:[]};
db.vehicles=db.vehicles||[];db.maintenance=db.maintenance||[];db.fuel=db.fuel||[];db.obligations=db.obligations||[];
db.vehicles.forEach(v=>{v.additional=v.additional||{};if(v.startKm==null)v.startKm=Number(v.km||0);});
function hydratePhotos(){if(typeof Android==='undefined')return;for(const v of db.vehicles){try{const stored=Android.getPhoto(v.id);if(stored)v.photo=stored;else if(v.photo&&v.photo.startsWith('data:image/')){Android.savePhoto(v.id,v.photo);v.photo='';}}catch(e){}}save();}

function migrateLegacy(){let changed=false;if(db.parts?.length){db.parts.forEach(p=>{let v=vehicle(p.vehicleId);if(v&&!db.maintenance.some(m=>m.legacyPartId===p.id)){db.maintenance.push({id:uid(),vehicleId:p.vehicleId,date:p.date||dateISO(),km:Number(p.km||v.km||0),types:['Otros'],otherText:p.description?`Pieza: ${p.description}`:'Pieza',total:Number(p.cost||0),breakdown:p.description&&Number(p.cost||0)>0?[{name:p.description,price:Number(p.cost)}]:[],notes:p.notes||'',next:null,legacyPartId:p.id});changed=true}});delete db.parts;changed=true}if(!db._obligationMigration){db.vehicles.forEach(v=>{let a=v.additional||{};if(Number(a.insuranceCost||0)>0){db.obligations.push({id:uid(),vehicleId:v.id,date:a.insuranceStart||dateISO(),type:'Seguro',cost:Number(a.insuranceCost),status:'',reason:'',notes:'Importado de una versión anterior'});changed=true}if(Number(a.taxCost||0)>0){db.obligations.push({id:uid(),vehicleId:v.id,date:a.taxDate||dateISO(),type:'Viñeta / impuesto',cost:Number(a.taxCost),status:'',reason:'',notes:'Importado de una versión anterior'});changed=true}});db._obligationMigration=true;changed=true}if(changed)save()}
function save(){
  try{
    const snapshot={...db,vehicles:db.vehicles.map(v=>{const c={...v};delete c.photo;return c;})};
    localStorage.setItem(KEY,JSON.stringify(snapshot));
    return true;
  }catch(e){
    toast(uiLang==='en'?'Could not save the data.':'No se han podido guardar los datos.');
    return false;
  }
}

